-- INFO: Create Schema
DROP SCHEMA IF EXISTS received_order CASCADE;
CREATE SCHEMA received_order;

-- INFO: Create Type Enum
CREATE TYPE received_order.order_status AS enum (
  'PREPARING',
  'IN_PROGRESS',
  'CANCELED',
  'COMPLETED'
);

-- INFO: Create Table(orders)
CREATE TABLE received_order.orders (
  order_no varchar(16) NOT NULL,
  CHECK (LENGTH(order_no) = 16),
  CHECK (order_no ~* '^ORD-[0-9]{8}-[0-9]{3}$'),

  order_date date NOT NULL DEFAULT current_date,

  order_pic varchar(5),
  CHECK (LENGTH(order_pic) = 5),
  CHECK (order_pic ~* '^U[0-9]{4}$'),

  customer_id varchar(8) NOT NULL,
  CHECK (LENGTH(customer_id) = 8),
  CHECK (customer_id ~* 'C[0-9]{7}$'),

  status received_order.order_status NOT NULL DEFAULT 'PREPARING',

  urgent boolean NOT NULL,

  note text,

  desired_delivery_time time,

  created_at timestamp with time zone NOT NULL,

  updated_at timestamp with time zone NOT NULL,

  created_by varchar(128) NOT NULL,
  CHECK (created_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$'),

  updated_by varchar(128) NOT NULL,
  CHECK (updated_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$')
);

-- INFO: Create Table(order_details)
CREATE TABLE received_order.order_details (
  order_no varchar(16) NOT NULL,
  CHECK (LENGTH(order_no) = 16),
  CHECK (order_no ~* '^ORD-[0-9]{8}-[0-9]{3}$'),

  detail_no bigint NOT NULL,
  CHECK (detail_no >= 1),

  product_no varchar(7) NOT NULL,
  CHECK (LENGTH(product_no) = 7),
  CHECK (product_no ~* 'P[0-9]{6}$'),

  order_quantity bigint NOT NULL,
  CHECK (order_quantity >= 1),

  shipping_quantity bigint NOT NULL DEFAULT 0,
  CHECK (shipping_quantity >= 0),

  cancel_quantity bigint NOT NULL DEFAULT 0,
  CHECK (cancel_quantity >= 0),

  remaining_quantity bigint NOT NULL,
  CHECK (remaining_quantity >= 0),

  status received_order.order_status NOT NULL DEFAULT 'PREPARING',

  selling_price bigint NOT NULL,
  CHECK (selling_price >= 1),

  cost_price bigint NOT NULL,
  CHECK (cost_price >= 0),

  profit_rate numeric(5,2) NOT NULL,
  CHECK (profit_rate >= 0.0),
  CHECK (profit_rate <= 100.0),

  created_at timestamp with time zone NOT NULL,

  updated_at timestamp with time zone NOT NULL,

  created_by varchar(128) NOT NULL,
  CHECK (created_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$'),

  updated_by varchar(128) NOT NULL,
  CHECK (updated_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$')
);

-- INFO: Create Table(shipping_instructions)
CREATE TABLE received_order.shipping_instructions (
  order_shipment_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,

  order_no varchar(16) NOT NULL,
  CHECK (LENGTH(order_no) = 16),
  CHECK (order_no ~* '^ORD-[0-9]{8}-[0-9]{3}$'),

  detail_no bigint NOT NULL,
  CHECK (detail_no >= 1),

  operation_date date NOT NULL DEFAULT current_date,

  person_in_charge varchar(5) NOT NULL,
  CHECK (LENGTH(person_in_charge) = 5),
  CHECK (person_in_charge ~* '^U[0-9]{4}$'),

  quantity bigint NOT NULL,
  CHECK (quantity >= 1),

  note text,

  created_at timestamp with time zone NOT NULL,

  updated_at timestamp with time zone NOT NULL,

  created_by varchar(128) NOT NULL,
  CHECK (created_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$'),

  updated_by varchar(128) NOT NULL,
  CHECK (updated_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$')
);

-- INFO: Create Table(cancel_instructions)
CREATE TABLE received_order.cancel_instructions (
  order_cancel_id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,

  order_no varchar(16) NOT NULL,
  CHECK (LENGTH(order_no) = 16),
  CHECK (order_no ~* '^ORD-[0-9]{8}-[0-9]{3}$'),

  detail_no bigint NOT NULL,
  CHECK (detail_no >= 1),

  operation_date date NOT NULL DEFAULT current_date,

  person_in_charge varchar(5) NOT NULL,
  CHECK (LENGTH(person_in_charge) = 5),
  CHECK (person_in_charge ~* '^U[0-9]{4}$'),

  quantity bigint NOT NULL,
  CHECK (quantity >= 1),

  note text,

  created_at timestamp with time zone NOT NULL,

  updated_at timestamp with time zone NOT NULL,

  created_by varchar(128) NOT NULL,
  CHECK (created_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$'),

  updated_by varchar(128) NOT NULL,
  CHECK (updated_by ~* '^[0-9A-HJKMNP-TV-Z]{26}::.+$')
);

