-- INFO: Custom Function
-- order_no の値を新たに採番する。
-- 番号体系は、ORD-YYYYMMDD-999 （処理日付ごとに001からの連番で取得する）
CREATE OR REPLACE FUNCTION received_order.generate_order_no(
  p_row received_order.orders
)
RETURNS varchar
LANGUAGE plpgsql
AS $$
DECLARE
  v_process_date text;
  v_max_no integer;
BEGIN
  -- 採番に使用する処理日付を取得する。
  v_process_date := to_char(current_date, 'YYYYMMDD');

  -- 同一処理日付の採番処理を直列化する。
  -- Transaction終了時にLockは自動的に解放される。
  PERFORM pg_advisory_xact_lock(
    hashtext('received_order.order_no.' || v_process_date)
  );

  -- 同一処理日付ですでに採番されている最大番号を取得する。
  SELECT COALESCE(MAX(RIGHT(order_no, 3)::integer), 0)
    INTO v_max_no
    FROM received_order.orders
   WHERE order_no LIKE 'ORD-' || v_process_date || '-%';

  -- 3桁で採番可能な上限を超えた場合はエラーとする。
  IF v_max_no >= 999 THEN
    RAISE EXCEPTION 'order_no sequence exceeded the daily limit (999): %', v_process_date;
  END IF;

  -- 最大番号に1を加算し、3桁ゼロ埋めして返却する。
  RETURN 'ORD-' || v_process_date || '-' || lpad((v_max_no + 1)::text, 3, '0');
END;
$$;

-- detail_no の値を新たに採番する。番号体系は、受注番号単位の連番。
CREATE OR REPLACE FUNCTION received_order.generate_detail_no(
  p_row received_order.order_details
)
RETURNS bigint
LANGUAGE plpgsql
AS $$
DECLARE
  v_max_no bigint;
BEGIN
  -- 同一受注番号の採番処理を直列化する。
  -- Transaction終了時にLockは自動的に解放される。
  PERFORM pg_advisory_xact_lock(
    hashtext('received_order.detail_no.' || p_row.order_no)
  );

  -- 同一受注番号における明細番号の最大値を取得する。
  SELECT COALESCE(MAX(detail_no), 0)
    INTO v_max_no
    FROM received_order.order_details
   WHERE order_no = p_row.order_no;

  RETURN v_max_no + 1;
END;
$$;

-- profit_rate の値を計算する。
CREATE OR REPLACE FUNCTION received_order.calculate_profit_rate(
  p_row received_order.order_details
)
RETURNS received_order.order_details
LANGUAGE plpgsql
AS $$
BEGIN
  -- profit_rateを計算する。
  p_row.profit_rate := (p_row.selling_price - p_row.cost_price) * 100.0 / p_row.selling_price;

  RETURN p_row;
END;
$$;

-- remaining_quantityを計算しstatusを判定する。
CREATE OR REPLACE FUNCTION received_order.calculate_quantity_and_status(
  p_row received_order.order_details
)
RETURNS received_order.order_details
LANGUAGE plpgsql
AS $$
DECLARE
  v_max_no integer;
BEGIN
  -- remaining_quantityを計算する。
  p_row.remaining_quantity := p_row.order_quantity - p_row.shipping_quantity - p_row.cancel_quantity;

  -- statusを判定する。
  IF p_row.order_quantity = p_row.remaining_quantity THEN
    p_row.status := 'PREPARING';
  ELSIF p_row.remaining_quantity = 0 AND p_row.shipping_quantity = 0 THEN
    p_row.status := 'CANCELED';
  ELSIF p_row.remaining_quantity = 0 THEN
    p_row.status := 'COMPLETED';
  ELSE
    p_row.status := 'IN_PROGRESS';
  END IF;

  RETURN p_row;
END;
$$;

-- 受注明細に出荷数を登録する。
CREATE OR REPLACE FUNCTION received_order.set_shipping_quantity(
  p_row received_order.shipping_instructions
)
RETURNS received_order.shipping_instructions
LANGUAGE plpgsql
AS $$
DECLARE
BEGIN
  -- 出荷数を登録する。
  UPDATE received_order.order_details
  SET shipping_quantity = shipping_quantity + p_row.quantity
  WHERE order_no = p_row.order_no AND detail_no = p_row.detail_no;

  RETURN p_row;
END;
$$;

-- 受注明細にキャンセル数を登録する。
CREATE OR REPLACE FUNCTION received_order.set_cancel_quantity(
  p_row received_order.cancel_instructions
)
RETURNS received_order.cancel_instructions
LANGUAGE plpgsql
AS $$
DECLARE
BEGIN
  -- キャンセル数を登録する。
  UPDATE received_order.order_details
  SET cancel_quantity = cancel_quantity + p_row.quantity
  WHERE order_no = p_row.order_no AND detail_no = p_row.detail_no;

  RETURN p_row;
END;
$$;

-- 受注ステータスを判定・登録する。
CREATE OR REPLACE FUNCTION received_order.judge_status(
  p_row received_order.order_details
)
RETURNS received_order.order_details
LANGUAGE plpgsql
AS $$
DECLARE
v_preparing_count INT;
v_canceled_count INT;
v_finished_count INT;
v_total_count INT;
v_status received_order.order_status;
BEGIN
  -- 受注明細のステータス別件数を取得する
    SELECT
    COUNT(*) FILTER (WHERE status = 'PREPARING'),
    COUNT(*) FILTER (WHERE status = 'CANCELED'),
    COUNT(*) FILTER (WHERE status IN ('COMPLETED', 'CANCELED')),
    COUNT(*)
  INTO
    v_preparing_count,
    v_canceled_count,
    v_finished_count,
    v_total_count
  FROM received_order.order_details
  WHERE order_no = p_row.order_no;

  -- ステータスを判定する
  IF v_preparing_count = v_total_count THEN
    v_status := 'PREPARING';

  ELSIF v_canceled_count = v_total_count THEN
    v_status := 'CANCELED';

  ELSIF v_finished_count = v_total_count THEN
    v_status := 'COMPLETED';

  ELSE
    v_status := 'IN_PROGRESS';
  END IF;

  -- 受注ステータスを登録する。
  UPDATE received_order.orders
  SET status = v_status
  WHERE order_no = p_row.order_no;

  RETURN p_row;
END;
$$;

